import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {ContentPreview} from '@github-ui/copilot-immersive-v1/components/ContentPreview/ContentPreview'
import {useResourcePanelOpen} from '@github-ui/copilot-immersive-v1/components/ContentPreview/ContentPreviewContext'
import {ResourcePanel} from '@github-ui/copilot-immersive-v1/components/ResourcePanel/ResourcePanel'

import styles from './EmbeddedContentPreview.module.css'

export function EmbeddedContentPreview({inputRef}: {inputRef: React.RefObject<HTMLTextAreaElement | null>}) {
  const resourcePanelOpen = useResourcePanelOpen()

  return (
    <div className={styles.contentPreview}>
      {copilotFeatureFlags.copilotResourcePanel && resourcePanelOpen && <ResourcePanel className="m-0" />}
      <ContentPreview className="m-0" returnFocusRef={inputRef} />
    </div>
  )
}

try{ EmbeddedContentPreview.displayName ||= 'EmbeddedContentPreview' } catch {}